CREATE TABLE IF NOT EXISTS settings (id int PRIMARY KEY DEFAULT 1 CHECK(id=1), data jsonb NOT NULL);
INSERT INTO settings VALUES(1,'{"shutdown":false,"purchasing":false,"inventory":0,"inventoryCostMicro":0,"baseTokensPerDollar":0,"globalDaily":100000000,"maximumDaily":1000000000,"userDaily":5000000,"newUserDaily":1000000,"promoTokens":1000000,"promoMicro":1000000,"promoMinAgeDays":0,"promoEnabled":true,"signupPromoConfigured":true,"holderRewardsEnabled":true,"holderRewardHoldSeconds":"43200","holderRewardMinTokens":"2000000","holderRewardBonusTokens":"10000000","holderRewardBaseGrant":"500000","holderRewardBonusGrant":"5000000","holderRewardExpiryDays":"7","holderRewardTiersV2":true}') ON CONFLICT DO NOTHING;
UPDATE settings SET data='{"holderRewardsEnabled":true,"holderRewardHoldSeconds":"43200","holderRewardMinTokens":"2000000","holderRewardBonusTokens":"10000000","holderRewardBaseGrant":"500000","holderRewardBonusGrant":"5000000","holderRewardExpiryDays":"7"}'::jsonb||data WHERE id=1;
UPDATE settings SET data=data||'{"holderRewardMinTokens":"2000000","holderRewardBonusTokens":"10000000","holderRewardBaseGrant":"500000","holderRewardBonusGrant":"5000000","holderRewardTiersV2":true}'::jsonb WHERE id=1 AND NOT(data?'holderRewardTiersV2');
UPDATE settings SET data=data||'{"giftsEnabled":true,"giftMinTokens":"100000","giftMaxTokens":"50000000","giftExpiryDays":"7"}'::jsonb WHERE id=1 AND NOT(data?'giftsEnabled');
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, x_id text UNIQUE NOT NULL, username text NOT NULL, role text NOT NULL DEFAULT 'user', suspended boolean NOT NULL DEFAULT false, email text UNIQUE, email_verified boolean NOT NULL DEFAULT false, wallet text, created_at timestamptz NOT NULL DEFAULT now(), x_created_at timestamptz, ip_hash text, device_hash text, purchased_micro bigint NOT NULL DEFAULT 0 CHECK(purchased_micro>=0), promo_micro bigint NOT NULL DEFAULT 0 CHECK(promo_micro>=0), base_tokens bigint NOT NULL DEFAULT 0 CHECK(base_tokens>=0), promo_tokens bigint NOT NULL DEFAULT 0 CHECK(promo_tokens>=0), promo_expires timestamptz, daily_limit bigint, monthly_limit_micro bigint);
ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar_url text;
CREATE TABLE IF NOT EXISTS sessions (hash text PRIMARY KEY, user_id uuid REFERENCES users(id), expires timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS challenges (hash text PRIMARY KEY, user_id uuid REFERENCES users(id), kind text NOT NULL, data jsonb NOT NULL, expires timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS promo_claims (x_id text PRIMARY KEY, email text UNIQUE, user_id uuid UNIQUE REFERENCES users(id), ip_hash text NOT NULL, device_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS holder_wallet_links (user_id uuid PRIMARY KEY REFERENCES users(id), wallet text UNIQUE NOT NULL CHECK(wallet=lower(wallet)), verified_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS holder_reward_claims (id uuid PRIMARY KEY, user_id uuid UNIQUE NOT NULL REFERENCES users(id), wallet text UNIQUE NOT NULL CHECK(wallet=lower(wallet)), balance_wei numeric(78,0) NOT NULL CHECK(balance_wei>=0), reward_tokens bigint NOT NULL CHECK(reward_tokens>0), reward_micro bigint NOT NULL CHECK(reward_micro>0), snapshot_block bigint NOT NULL CHECK(snapshot_block>0), holding_since timestamptz NOT NULL, claimed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS providers (id uuid PRIMARY KEY, name text NOT NULL, base_url text NOT NULL, encrypted_key text NOT NULL, priority int NOT NULL DEFAULT 10, enabled boolean NOT NULL DEFAULT true, verified_at timestamptz);
CREATE TABLE IF NOT EXISTS models (id text PRIMARY KEY, name text NOT NULL, family text NOT NULL, upstream_id text NOT NULL, enabled boolean NOT NULL DEFAULT false, verified boolean NOT NULL DEFAULT false, ratio numeric NOT NULL CHECK(ratio>0), input_rate numeric, output_rate numeric, cached_rate numeric, reasoning_rate numeric, official_input_rate numeric, official_output_rate numeric, max_context int NOT NULL DEFAULT 32768, max_output int NOT NULL DEFAULT 4096, promo boolean NOT NULL DEFAULT false, vision boolean NOT NULL DEFAULT false, tools boolean NOT NULL DEFAULT false, json_format boolean NOT NULL DEFAULT false, premium boolean NOT NULL DEFAULT false, aliases text[] NOT NULL DEFAULT '{}', provider_ids uuid[] NOT NULL DEFAULT '{}');
ALTER TABLE models ADD COLUMN IF NOT EXISTS auto_enabled boolean NOT NULL DEFAULT true;
ALTER TABLE models ADD COLUMN IF NOT EXISTS auto_quality int NOT NULL DEFAULT 50 CHECK(auto_quality BETWEEN 0 AND 100);
WITH signup_promo AS (UPDATE settings SET data=data||'{"promoEnabled":true,"promoTokens":1000000,"promoMicro":1000000,"promoMinAgeDays":0,"signupPromoConfigured":true}'::jsonb WHERE id=1 AND NOT(data?'signupPromoConfigured') RETURNING 1) UPDATE models SET promo=true WHERE ratio<=1 AND NOT premium AND EXISTS(SELECT 1 FROM signup_promo);
CREATE TABLE IF NOT EXISTS api_keys (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, hash text UNIQUE NOT NULL, prefix text NOT NULL, revoked boolean NOT NULL DEFAULT false, allowed_models text[] NOT NULL DEFAULT '{}', spending_cap bigint, token_cap bigint, daily_cap bigint, monthly_cap bigint, rpm int NOT NULL DEFAULT 30 CHECK(rpm BETWEEN 1 AND 300), expires timestamptz, created_at timestamptz NOT NULL DEFAULT now(), spent_micro bigint NOT NULL DEFAULT 0, spent_tokens bigint NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS reservations (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), key_id uuid NOT NULL REFERENCES api_keys(id), model_id text NOT NULL, state text NOT NULL DEFAULT 'reserved', purchased_micro bigint NOT NULL, promo_micro bigint NOT NULL, base_tokens bigint NOT NULL, promo_tokens bigint NOT NULL, max_micro bigint NOT NULL, max_weighted bigint NOT NULL, usage_day date NOT NULL DEFAULT CURRENT_DATE, rates jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS daily_capacity (day date PRIMARY KEY, used bigint NOT NULL DEFAULT 0 CHECK(used>=0));
CREATE TABLE IF NOT EXISTS user_daily (user_id uuid REFERENCES users(id), day date, weighted bigint NOT NULL DEFAULT 0 CHECK(weighted>=0), micro bigint NOT NULL DEFAULT 0 CHECK(micro>=0), PRIMARY KEY(user_id,day));
CREATE TABLE IF NOT EXISTS key_daily (key_id uuid REFERENCES api_keys(id), day date, micro bigint NOT NULL DEFAULT 0 CHECK(micro>=0), PRIMARY KEY(key_id,day));
CREATE TABLE IF NOT EXISTS ledgers (id bigserial PRIMARY KEY, user_id uuid REFERENCES users(id), kind text NOT NULL, delta bigint NOT NULL, reference text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(kind,reference));
CREATE TABLE IF NOT EXISTS requests (id uuid PRIMARY KEY, user_id uuid REFERENCES users(id), key_id uuid REFERENCES api_keys(id), model_id text NOT NULL, provider_id uuid, status int NOT NULL, input_tokens bigint NOT NULL DEFAULT 0, cached_tokens bigint NOT NULL DEFAULT 0, reasoning_tokens bigint NOT NULL DEFAULT 0, output_tokens bigint NOT NULL DEFAULT 0, actual_tokens bigint NOT NULL DEFAULT 0, weighted_tokens bigint NOT NULL DEFAULT 0, charged_micro bigint NOT NULL DEFAULT 0, upstream_cost_micro bigint NOT NULL DEFAULT 0, latency_ms int NOT NULL, error_code text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS requests_user_time ON requests(user_id,created_at);
CREATE TABLE IF NOT EXISTS orders (id uuid PRIMARY KEY, user_id uuid REFERENCES users(id), chain_id int NOT NULL, wallet text NOT NULL, treasury text NOT NULL, pay_usd int NOT NULL, credit_micro bigint NOT NULL, base_tokens bigint NOT NULL, wei numeric(78,0) NOT NULL, quote_price text NOT NULL, state text NOT NULL DEFAULT 'pending', tx_hash text, created_at timestamptz NOT NULL DEFAULT now(), expires timestamptz NOT NULL, confirmed_at timestamptz, UNIQUE(chain_id,tx_hash));
CREATE TABLE IF NOT EXISTS credit_gifts (id uuid PRIMARY KEY, sender_user_id uuid NOT NULL REFERENCES users(id), recipient_user_id uuid REFERENCES users(id), recipient_kind text NOT NULL CHECK(recipient_kind IN ('x','email','link')), recipient_hint text NOT NULL, claim_hash text UNIQUE, credit_micro bigint NOT NULL CHECK(credit_micro>0), base_tokens bigint NOT NULL CHECK(base_tokens>0), note text, state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','claimed','cancelled','expired')), email_sent boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, claimed_at timestamptz, cancelled_at timestamptz);
CREATE INDEX IF NOT EXISTS credit_gifts_sender_time ON credit_gifts(sender_user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS credit_gifts_recipient_time ON credit_gifts(recipient_user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS credit_gifts_pending_expiry ON credit_gifts(expires_at) WHERE state='pending';
CREATE TABLE IF NOT EXISTS audit (id bigserial PRIMARY KEY, actor uuid REFERENCES users(id), action text NOT NULL, target text, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS product_updates (id uuid PRIMARY KEY, title text NOT NULL, description text NOT NULL, status text NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','building','testing','live')), eta text, link text, position int NOT NULL DEFAULT 0, published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS product_updates_public ON product_updates(published,position,created_at DESC);
CREATE TABLE IF NOT EXISTS app_migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());

ALTER TABLE users ADD COLUMN IF NOT EXISTS sol_wallet text;
ALTER TABLE promo_claims ALTER COLUMN email DROP NOT NULL;
